require("addon")

-- Global credentials (can be loaded from account_config.lua or defaulted)
local PASSWORD = ""
local AUTO_LOGIN_ENABLED = true

-- Safely load dynamic account config generated by BotService
pcall(function()
    dofile("scripts/account_config.lua")
end)
pcall(function()
    dofile("account_config.lua")
end)

local hasAttemptedLogin = false
local isReconnecting = false
local loginAttempts = 0

function onLoad()
    print("[AutoLogin] Script active. Auto-login enabled (Pure Sleep Mode / اسلیپ دائم).")
end

function onDisconnect()
    hasAttemptedLogin = false
    isReconnecting = false
    loginAttempts = 0
    print("[AutoLogin] Disconnected from server. Session reset.")
end

function onPrintLog(text)
    if not text then return end

    local lower = text:lower()

    if lower:find("put to sleep") or lower:find("using raksamp") then
        print("[AutoLogin] >>> Account confirmed in Sleep Mode (اسلیپ فعال است).")
    end

    -- Reconnect trigger on server kick, disconnect, or notice
    if not isReconnecting then
        local myNick = (getBotNick and getBotNick()) or ""
        local isMyKick = (myNick ~= "" and lower:find(myNick:lower(), 1, true) and lower:find("kicked by admbot", 1, true))
        
        if lower:find("already logged in", 1, true) then
            isReconnecting = true
            print("[AutoLogin] Account already logged in! Waiting 30s before retry to avoid IP ban...")
            newTask(function()
                wait(30000)
                reconnect(5000)
            end)
        elseif lower:find("you are banned", 1, true) then
            isReconnecting = true
            print("[AutoLogin] Temporary IP ban detected. Waiting 60s before retry...")
            newTask(function()
                wait(60000)
                reconnect(5000)
            end)
        elseif lower:find("you have been kicked", 1, true) or isMyKick or lower:find("server closed the connection", 1, true) or lower:find("connection was closed", 1, true) then
            isReconnecting = true
            print("[AutoLogin] Server disconnect/kick detected: " .. text .. ". Waiting 10s before reconnecting...")
            newTask(function()
                wait(10000)
                reconnect(3000)
            end)
        end
    end
end

function onReceiveRPC(id, bs)
    if id == RPC_ScrDialogBox then
        local wDialogID = bs:readUInt16()
        local bDialogStyle = bs:readUInt8()
        local bTitleLength = bs:readUInt8()
        local szTitle = (bTitleLength and bTitleLength > 0) and bs:readString(bTitleLength) or ""

        -- 1. Handle launcher warning or notice dialog (ID 1 or launcher/notice)
        if wDialogID == 1 or (szTitle and (szTitle:lower():find("launcher") or szTitle:lower():find("notice") or szTitle:lower():find("warning"))) then
            print(string.format("[AutoLogin] Notice/Launcher dialog (ID: %d) received. Auto-confirming...", wDialogID))
            newTask(function()
                wait(500)
                sendDialogResponse(wDialogID, 1, 0, "")
            end)
            return false
        end

        -- 2. Handle stats dialog auto-close
        if szTitle and (szTitle:lower():find("stats") or szTitle:lower():find("status")) then
            print("[AutoStats] Stats dialog received. Auto-closing...")
            newTask(function()
                wait(500)
                sendDialogResponse(wDialogID, 1, 0, "")
            end)
            return false
        end

        -- 3. Check for login dialog (Dialog ID 2 or 3 or title containing login, or password style 3)
        local titleLower = (szTitle and szTitle:lower()) or ""
        local isLoginDialog = (wDialogID == 2 or wDialogID == 3 or titleLower:find("login") or bDialogStyle == 3)

        if isLoginDialog and AUTO_LOGIN_ENABLED and PASSWORD ~= "" then
            if loginAttempts < 3 then
                loginAttempts = loginAttempts + 1
                hasAttemptedLogin = true
                print(string.format("[AutoLogin] Login dialog (ID: %d, Attempt: %d) detected. Automatically sending password...", wDialogID, loginAttempts))

                newTask(function()
                    wait(600)
                    sendDialogResponse(wDialogID, 1, 0, PASSWORD)
                    print("[AutoLogin] Password submitted successfully. Bot will remain in Sleep Mode (بدون اسپاون).")

                    -- Wait for sleep state confirmation and update stats once
                    wait(4000)
                    sendInput("/stats")
                end)
                return false
            else
                print("[AutoLogin] ⚠️ خطا: پسورد ارسال شد اما سرور مجدداً درخواست رمز کرد. لطفاً صحت رمز عبور را بررسی نمایید.")
            end
        end
    end
end
